import { useState, type FormEvent } from "react";
import { CheckCircle2 } from "lucide-react";
import { Link } from "../lib/router";
import { useCollection } from "../lib/data";
import { schema, stores, type Row } from "../data/stores";
import { inputType } from "../lib/format";

const content = {
  "title": "Nuevo prospecto",
  "subtitle": "",
  "entity": "prospectos",
  "cta": {
    "label": "Volver a la lista",
    "href": "/prospectos"
  },
  "submit": "Guardar"
};

export default function FormularioDeAlta() {
  const entity = schema[content.entity];
  const store = stores[content.entity];
  const [saved, setSaved] = useState<Row | null>(null);
  const [error, setError] = useState("");
  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    const values: Record<string, unknown> = {};
    for (const field of entity.fields) {
      const raw = data.get(field.key);
      if (field.type === "boolean") values[field.key] = raw === "on";
      else if (field.type === "number" || field.type === "money") values[field.key] = raw === "" || raw === null ? null : Number(raw);
      else values[field.key] = String(raw ?? "").trim();
      if (field.required && (values[field.key] === "" || values[field.key] === null)) {
        setError("Completa: " + field.label);
        return;
      }
    }
    setError("");
    setSaved(store.create(values));
    event.currentTarget.reset();
  }
  return (
    <div className="mx-auto max-w-2xl space-y-6">
      <div>
        <h1 className="font-display text-3xl font-bold tracking-tight">{content.title}</h1>
        {content.subtitle ? <p className="mt-1 text-sm text-muted">{content.subtitle}</p> : null}
      </div>
      {saved ? (
        <div className="flex items-start gap-3 rounded-card border border-line bg-surface-2 p-4 text-sm">
          <CheckCircle2 className="mt-0.5 size-5 shrink-0 text-primary" />
          <div>
            <p className="font-semibold">{entity.singular} guardado.</p>
            {content.cta ? <Link to={content.cta.href} className="mt-1 inline-block font-semibold text-primary">{content.cta.label}</Link> : null}
          </div>
        </div>
      ) : null}
      <form onSubmit={submit} className="rounded-card border border-line bg-surface p-6 shadow-card grid gap-4 sm:grid-cols-2" noValidate>
        {entity.fields.map((field) => (
          <label key={field.key} className={"grid gap-1.5 text-sm font-medium " + (field.type === "longtext" ? "sm:col-span-2" : "")}>
            <span>{field.label}{field.required ? <span className="text-primary"> *</span> : null}</span>
            {field.type === "select" ? (
              <select name={field.key} className="w-full rounded-input border border-line bg-bg px-3 py-2.5 text-sm text-ink outline-none focus:border-primary" defaultValue="">
                <option value="" disabled>Elige una opción</option>
                {(field.options ?? []).map((option) => <option key={option}>{option}</option>)}
              </select>
            ) : field.type === "longtext" ? (
              <textarea name={field.key} rows={4} className="w-full rounded-input border border-line bg-bg px-3 py-2.5 text-sm text-ink outline-none focus:border-primary" />
            ) : field.type === "boolean" ? (
              <input type="checkbox" name={field.key} className="size-5 accent-[var(--color-primary)]" />
            ) : (
              <input name={field.key} type={inputType(field)} step={field.type === "money" ? "0.01" : undefined} className="w-full rounded-input border border-line bg-bg px-3 py-2.5 text-sm text-ink outline-none focus:border-primary" />
            )}
          </label>
        ))}
        {error ? <p className="text-sm font-medium text-primary sm:col-span-2">{error}</p> : null}
        <div className="flex gap-3 sm:col-span-2">
          <button type="submit" className="inline-flex items-center justify-center gap-2 rounded-btn bg-primary px-6 py-3 text-sm font-semibold text-primary-ink shadow-card transition hover:-translate-y-0.5 hover:opacity-95">{content.submit}</button>
          {content.cta ? <Link to={content.cta.href} className="inline-flex items-center justify-center gap-2 rounded-btn border border-line bg-surface px-6 py-3 text-sm font-semibold text-ink transition hover:bg-surface-2">Cancelar</Link> : null}
        </div>
      </form>
    </div>
  );
}

import { BarChart3 } from "lucide-react";
import { useCollection } from "../lib/data";
import { schema, stores, type Row } from "../data/stores";
import { formatValue } from "../lib/format";

const content = {
  "title": "Valor por etapa",
  "subtitle": "",
  "entity": "prospectos",
  "field": "etapa"
};

export default function Grafica() {
  const entity = schema[content.entity];
  const rows = useCollection(stores[content.entity]);
  const group = entity.fields.find((field) => field.key === content.field) ?? entity.fields.find((field) => field.type === "select");
  const money = entity.fields.find((field) => field.type === "money");
  const buckets = new Map<string, number>();
  for (const row of rows) {
    const key = group ? String(row[group.key] ?? "Sin dato") : new Date(row.createdAt).toLocaleDateString("es-MX", { month: "short" });
    buckets.set(key, (buckets.get(key) ?? 0) + (money ? Number(row[money.key]) || 0 : 1));
  }
  const data = [...buckets.entries()];
  const max = Math.max(1, ...data.map(([, value]) => value));
  return (
    <div className="rounded-card border border-line bg-surface p-6 shadow-card">
      <div className="flex items-center gap-3">
        <span className="grid size-10 place-items-center rounded-btn bg-surface-2 text-primary"><BarChart3 className="size-5" /></span>
        <div>
          <h2 className="font-display text-xl font-semibold">{content.title}</h2>
          {content.subtitle ? <p className="text-sm text-muted">{content.subtitle}</p> : null}
        </div>
      </div>
      {data.length ? (
        <div className="mt-8 flex h-56 items-end gap-3">
          {data.map(([name, value]) => (
            <div key={name} className="flex flex-1 flex-col items-center gap-2">
              <span className="text-xs font-semibold">{money ? formatValue(money, value) : value}</span>
              <div className="w-full rounded-t-btn bg-primary transition-all" style={{ height: Math.max(6, (value / max) * 180) + "px" }} />
              <span className="truncate text-xs text-muted">{name}</span>
            </div>
          ))}
        </div>
      ) : (
        <p className="mt-6 text-sm text-muted">Agrega registros para ver la gráfica.</p>
      )}
    </div>
  );
}

import { useMemo, useState } from "react";
import { Plus, Search, Trash2 } from "lucide-react";
import { Link } from "../lib/router";
import { useCollection } from "../lib/data";
import { schema, stores, type Row } from "../data/stores";
import { formatValue } from "../lib/format";

const content = {
  "title": "Prospectos",
