        </div>
        {content.cta ? <Link to={content.cta.href} className="inline-flex items-center justify-center gap-2 rounded-btn bg-primary px-6 py-3 text-sm font-semibold text-primary-ink shadow-card transition hover:-translate-y-0.5 hover:opacity-95"><Plus className="size-4" />{content.cta.label}</Link> : null}
