          <select value={filter} onChange={(event) => setFilter(event.target.value)} className="w-full rounded-input border border-line bg-bg px-3 py-2.5 text-sm text-ink outline-none focus:border-primary sm:w-56" aria-label={filterField.label}>
            <option value="">Todos</option>
            {(filterField.options ?? []).map((option) => <option key={option}>{option}</option>)}
