import { ArrowUpRight, TrendingUp } from "lucide-react";
import { Link } from "../lib/router";
import { useCollection } from "../lib/data";
import { schema, stores, type Row } from "../data/stores";
import { formatValue, primaryField } from "../lib/format";

type Cta = { label: string; href: string };

const content = {
  "title": "Resumen del embudo",
  "subtitle": "Así va tu mes",
  "keys": [
    "prospectos"
  ],
  "main": "prospectos",
  "cta": null as Cta | null
};

export default function Tablero() {
  const lists = content.keys.map((key) => ({ key, rows: useCollection(stores[key]) }));
  const mainRows = lists.find((entry) => entry.key === content.main)?.rows ?? [];
  const mainSchema = schema[content.main];
  const money = mainSchema.fields.find((field) => field.type === "money");
  const total = money ? mainRows.reduce((sum, row) => sum + (Number(row[money.key]) || 0), 0) : null;
  const label = primaryField(mainSchema);
  const recent = [...mainRows].sort((a, b) => b.createdAt.localeCompare(a.createdAt)).slice(0, 6);
  const group = mainSchema.fields.find((field) => field.type === "select");
  const groups = group
    ? (group.options ?? []).map((option) => {
        const rows = mainRows.filter((row) => row[group.key] === option);
        return { option, count: rows.length, amount: money ? rows.reduce((sum, row) => sum + (Number(row[money.key]) || 0), 0) : 0 };
      })
    : [];
  const peak = Math.max(1, ...groups.map((entry) => (money ? entry.amount : entry.count)));
  return (
    <div className="space-y-8">
      <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end">
        <div>
          <h1 className="font-display text-3xl font-bold tracking-tight">{content.title}</h1>
          {content.subtitle ? <p className="mt-1 text-sm text-muted">{content.subtitle}</p> : null}
        </div>
        {content.cta ? <Link to={content.cta.href} className="inline-flex items-center justify-center gap-2 rounded-btn bg-primary px-6 py-3 text-sm font-semibold text-primary-ink shadow-card transition hover:-translate-y-0.5 hover:opacity-95">{content.cta.label}</Link> : null}
      </div>
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        {lists.map((entry) => (
          <div key={entry.key} className="rounded-card border border-line bg-surface p-6 shadow-card">
            <p className="text-sm text-muted">{schema[entry.key].label}</p>
            <p className="mt-2 font-display text-3xl font-bold">{entry.rows.length}</p>
          </div>
        ))}
        {money && total !== null ? (
          <div className="rounded-card bg-primary p-6 text-primary-ink shadow-card">
            <p className="flex items-center gap-2 text-sm opacity-80"><TrendingUp className="size-4" />{money.label}</p>
            <p className="mt-2 font-display text-3xl font-bold">{formatValue(money, total)}</p>
          </div>
        ) : null}
        {money && mainRows.length ? (
          <div className="rounded-card border border-line bg-surface p-6 shadow-card">
            <p className="text-sm text-muted">Promedio</p>
            <p className="mt-2 font-display text-3xl font-bold">{formatValue(money, (total ?? 0) / mainRows.length)}</p>
          </div>
        ) : null}
      </div>
      <div className="grid gap-4 lg:grid-cols-3">
        {group ? (
          <div className="rounded-card border border-line bg-surface p-6 shadow-card">
            <p className="font-display text-lg font-semibold">Por {group.label.toLowerCase()}</p>
            <ul className="mt-5 space-y-4">
              {groups.map((entry) => (
                <li key={entry.option}>
                  <div className="flex items-center justify-between text-sm">
                    <span className="font-medium">{entry.option}</span>
                    <span className="text-muted">{money ? formatValue(money, entry.amount) : entry.count}</span>
                  </div>
                  <div className="mt-2 h-2 rounded-full bg-surface-2">
                    <div className="h-2 rounded-full bg-primary" style={{ width: `${Math.round(((money ? entry.amount : entry.count) / peak) * 100)}%` }} />
                  </div>
                </li>
              ))}
            </ul>
          </div>
        ) : null}
        <div className={`rounded-card border border-line bg-surface p-6 shadow-card ${group ? "lg:col-span-2" : "lg:col-span-3"}`}>
          <p className="font-display text-lg font-semibold">Recientes · {mainSchema.label}</p>
          {recent.length ? (
            <ul className="mt-4 divide-y divide-line">
              {recent.map((row: Row) => (
                <li key={row.id} className="flex items-center justify-between gap-4 py-3 text-sm">
                  <span className="font-medium">{String(row[label.key] ?? "")}</span>
                  <span className="flex items-center gap-3 text-muted">
                    {group && row[group.key] ? <span className="rounded-full bg-surface-2 px-2.5 py-0.5 text-xs font-medium text-ink">{String(row[group.key])}</span> : null}
                    {money ? formatValue(money, row[money.key]) : new Date(row.createdAt).toLocaleDateString("es-MX")}
                    <ArrowUpRight className="size-3.5" />
                  </span>
                </li>
              ))}
            </ul>
          ) : (
            <p className="mt-4 text-sm text-muted">Aún no hay registros.</p>
          )}
        </div>
      </div>
    </div>
  );
}

import { ChevronRight } from "lucide-react";
import { useCollection } from "../lib/data";
import { schema, stores, type Row } from "../data/stores";
import { primaryField } from "../lib/format";

const content = {
  "title": "Embudo por etapa",
  "subtitle": "",
  "entity": "prospectos",
  "field": "etapa"
};

export default function TableroKanban() {
  const entity = schema[content.entity];
  const store = stores[content.entity];
  const rows = useCollection(store);
  const group = entity.fields.find((field) => field.key === content.field) ?? entity.fields.find((field) => field.type === "select");
  const columns = group?.options?.length ? group.options : ["Pendiente", "En curso", "Listo"];
  const label = primaryField(entity);
  function move(row: Row, step: number) {
    if (!group) return;
    const index = columns.indexOf(String(row[group.key] ?? columns[0]));
    const next = columns[Math.min(columns.length - 1, Math.max(0, index + step))];
    store.update(row.id, { [group.key]: next });
  }
  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-display text-3xl font-bold tracking-tight">{content.title}</h1>
        {content.subtitle ? <p className="mt-1 text-sm text-muted">{content.subtitle}</p> : null}
      </div>
      <div className="grid gap-4 md:grid-flow-col md:auto-cols-fr">
        {columns.map((column) => {
          const cards = rows.filter((row: Row) => String(row[group?.key ?? ""] ?? columns[0]) === column);
          return (
            <section key={column} className="rounded-card border border-line bg-surface-2/60 p-3">
              <p className="flex items-center justify-between px-1 pb-3 text-sm font-semibold">{column}<span className="rounded-full bg-surface px-2 text-xs text-muted">{cards.length}</span></p>
              <div className="grid gap-2">
                {cards.map((row: Row) => (
                  <article key={row.id} className="rounded-btn border border-line bg-surface p-3 text-sm shadow-card">
                    <p className="font-medium">{String(row[label.key] ?? "")}</p>
                    <div className="mt-3 flex justify-between">
                      <button type="button" onClick={() => move(row, -1)} className="text-xs text-muted hover:text-ink" disabled={column === columns[0]}>Atrás</button>
                      <button type="button" onClick={() => move(row, 1)} className="inline-flex items-center gap-1 text-xs font-semibold text-primary" disabled={column === columns[columns.length - 1]}>Avanzar<ChevronRight className="size-3.5" /></button>
                    </div>
                  </article>
                ))}
                {cards.length ? null : <p className="px-1 py-4 text-center text-xs text-muted">Sin elementos</p>}
              </div>
            </section>
          );
        })}
      </div>
    </div>
  );
}

